fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let r: i32 = 2048 + host::display::pointer_x() * 2048 / w;
    host::display::clear(0x0c0c0c);
    host::display::fill_rect(30, h - 70, w - 60, 1, 0x303030);
    let mut x: i32 = 300;
    let mut k: i32 = 0;
    while k < 100 {
        x = ((r * x >> 10) * (1024 - x)) >> 10;
        if x < 1 { x = 1; }
        if x > 1023 { x = 1023; }
        if k >= 40 {
            let px: i32 = 40 + (k - 40) * 7;
            let py: i32 = h - 80 - x * (h - 160) / 1024;
            host::display::fill_rect(px, py, 4, 4, 0x70e0a0);
        }
        k = k + 1;
    }
    host::display::draw_string(30, 20, "LOGISTIC MAP", 0x808080, 2);
    host::display::draw_string(30, 50, "R X1000", 0x606060, 1);
    host::display::draw_number(110, 50, (r * 1000) >> 10, 0xffffff, 1);
    host::display::draw_string(30, h - 40, "DRAG X TO SET R", 0x505050, 1);
    host::display::present();
}
